#include <condition_variable>
#include <functional>
#include <future>
#include <memory>
#include <mutex>
#include <queue>
#include <thread>
#include <vector>

class ThreadPool {
    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex m_;
    std::condition_variable cv_;
    bool stop_ = false;
public:
    explicit ThreadPool(unsigned n) {
        for (unsigned i = 0; i < n; ++i)
            workers_.emplace_back([this] {
                for (;;) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lk(m_);
                        cv_.wait(lk, [this] { return stop_ || !tasks_.empty(); });
                        if (stop_ && tasks_.empty()) return;
                        task = std::move(tasks_.front());
                        tasks_.pop();
                    }
                    task();                          // run OUTSIDE the lock
                }
            });
    }
    ~ThreadPool() {
        {   std::unique_lock<std::mutex> lk(m_);
            stop_ = true;
        }
        cv_.notify_all();
        for (auto& t : workers_) t.join();
    }
    template <class F>
    auto submit(F f) -> std::future<decltype(f())> {
        using R = decltype(f());
        // packaged_task is move-only, but std::function requires copyable:
        // wrap in shared_ptr so the lambda copied into the queue is copyable.
        auto pt = std::make_shared<std::packaged_task<R()>>(std::move(f));
        std::future<R> fut = pt->get_future();
        {   std::unique_lock<std::mutex> lk(m_);
            tasks_.emplace([pt] { (*pt)(); });
        }
        cv_.notify_one();
        return fut;
    }
};

int main() {
    ThreadPool pool(4);
    auto f = pool.submit([] { return 2 + 2; });
    std::cout << f.get() << '\n';                    // 4
    return 0;
}

#include <future>
#include <vector>
#include <numeric>
#include <cstdio>

// Price three books concurrently, sum the results.
// The pool is implicit (std::async with the launch policy), the join is the .get()s.
double total_pnl(std::vector<double> book_a,
                 std::vector<double> book_b,
                 std::vector<double> book_c) {
    auto sum = [](std::vector<double> v) {
        return std::accumulate(v.begin(), v.end(), 0.0);
    };
    auto fa = std::async(std::launch::async, sum, std::move(book_a));
    auto fb = std::async(std::launch::async, sum, std::move(book_b));
    double c = sum(book_c);                      // do one on this thread
    return fa.get() + fb.get() + c;              // .get() joins + rethrows
}

int main() {
    printf("%.2f\n", total_pnl({1,2,3}, {4,5}, {-2}));   // 13.00
}

